"""Scanners that read git history and extract AI-agent indicator signals."""
import re
import subprocess

# Trailers/tools that explicitly mark AI participation
AGENT_TRAILERS = [
    "co-authored-by: claude", "co-authored-by: github copilot",
    "co-authored-by: chatgpt", "co-authored-by: gpt", "generated by github copilot",
    "assisted by cursor", "generated by gemini", "co-authored-by: gemini",
    "co-authored-by: codex", "co-authored-by: copilot",
]

# Phrasings strongly associated with LLM-authored messages
STYLE_PATTERNS = [
    (re.compile(r"\bthis (change|commit|pr) (adds|fixes|updates|removes|introduces)\b", re.I), "llm opener"),
    (re.compile(r"\bproper(ly)? (handle|handled)\b.*\berror", re.I), "llm error idiom"),
    (re.compile(r"\bensure[sd]?\b.*\bcorrect(ness)?\b", re.I), "llm correctness idiom"),
    (re.compile(r"\bno (functional )?changes?\b.*\bbehavior(e?u?r)?\b", re.I), "llm disclaimer"),
    (re.compile(r"^(?:feat|fix|docs|chore|refactor|test|style|perf|build|ci)(\([^)]+\))?!?: .+", re.M), "conventional commit"),
]


def git_log(path):
    """Return the last 500 commits as a list of dicts."""
    out = subprocess.run(
        ["git", "log", "-500", "--pretty=format:%H%x1f%an%x1f%ae%x1f%s%x1f%b%x1e"],
        cwd=path, capture_output=True, text=True, check=True,
    ).stdout
    commits = []
    for rec in (r for r in out.split("\x1e") if r.strip()):
        fields = rec.strip("\n").split("\x1f")
        fields += [""] * (5 - len(fields))
        commits.append({"hash": fields[0], "author": fields[1], "email": fields[2],
                        "subject": fields[3], "body": fields[4]})
    return commits


def trailer_hits(commit):
    """Return agent-trailer matches found in a commit message."""
    msg = f"{commit['subject']}\n{commit['body']}".lower()
    return [t for t in AGENT_TRAILERS if t in msg]


def style_hits(commit):
    """Return (label, count) style-imperative matches for a commit message."""
    msg = f"{commit['subject']}\n{commit['body']}"
    hits = []
    for pattern, label in STYLE_PATTERNS:
        n = len(pattern.findall(msg))
        if n:
            hits.append((label, n))
    return hits


def em_dash_count(commit):
    """LLMs overuse em dashes; humans rarely type them."""
    return (f"{commit['subject']}{commit['body']}").count("\u2014")
